SINA_SMART["parasito-intro"] = {"lecture":"parasito-intro","title":"Introduction to parasitology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-intro:e0","text":"Parasite: eukaryote living at a host's expense.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e1","text":"Protozoa (unicellular) vs metazoa (helminths, arthropods).","topic":"Classification","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e2","text":"Helminths: nematodes, cestodes, trematodes.","topic":"Classification","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e3","text":"Parasitism vs commensalism vs symbiosis.","topic":"Associations between living beings","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e4","text":"Dead end: unusual host, no adult stage (larva migrans, hydatid cyst in humans).","topic":"Associations between living beings","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e5","text":"Ectoparasite → infestation; endoparasite → infection.","topic":"Associations between living beings","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e6","text":"Entry: ingestion, skin (Schistosoma), transplacental (Toxoplasma), bite (Plasmodium).","topic":"Entry, exit and harm","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e7","text":"Definitive host = adult/sexual; intermediate host = larval/asexual.","topic":"Cycles and epidemiological actors","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e8","text":"Direct short (amoeba), direct long (Ancylostoma), indirect (Taenia).","topic":"Cycles and epidemiological actors","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-intro:e9","text":"Pinworm: evening anal itch, scotch test, albendazole repeated at 15-21 days.","topic":"Cycles and epidemiological actors","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"18sr8jl":"a","dxh9a":"a","9bw49c":"a","e91mmb":"a","w9nmo8":"a","9sf4ya":"a","m3zfqq":"a","z3mvie":"a","sl4sci":"a","otj3lh":"a","y9wmxt":"a","qs6e8j":"a","14a2ypq":"a","1ss3cqs":"a","1xgs4z1":"a","nafgyh":"x"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-intro:e0":{"s":0,"u":["Parasite: eukaryote living at a host's expense.","A parasite is a eukaryotic infectious agent that, during its life cycle, develops temporarily or permanently at the expense of another eukaryotic living being, the host , harming it without necessarily killing it (unlike a predator)."],"dp":[]},"parasito-intro:e1":{"s":1,"u":["Protozoa (unicellular) vs metazoa (helminths, arthropods).","Two sub-kingdoms: Protozoa (unicellular; classified by morphology and locomotion): intestinal ( Entamoeba histolytica, Giardia, Cryptosporidium ), blood and tissue ( Plasmodium, Toxoplasma, Trypanosoma, Leishmania ), urogenital ( Trichomonas vaginalis ); Metazoa (multicellular): helminths : nematodes (roundworms: Ascaris ), cestodes (flatworms: Taenia ), trematodes (flukes: Schistosoma, Fasciola ); and arthropods (external skeleton)."],"dp":[]},"parasito-intro:e2":{"s":1,"u":["Helminths: nematodes, cestodes, trematodes.","Two sub-kingdoms: Protozoa (unicellular; classified by morphology and locomotion): intestinal ( Entamoeba histolytica, Giardia, Cryptosporidium ), blood and tissue ( Plasmodium, Toxoplasma, Trypanosoma, Leishmania ), urogenital ( Trichomonas vaginalis ); Metazoa (multicellular): helminths : nematodes (roundworms: Ascaris ), cestodes (flatworms: Taenia ), trematodes (flukes: Schistosoma, Fasciola ); and arthropods (external skeleton)."],"dp":[]},"parasito-intro:e3":{"s":2,"u":["Parasitism vs commensalism vs symbiosis.","Symbiosis/mutualism : both benefit (lichen; flagellates in termites).","Commensalism (\"who eats with\"): benefits one, neutral for the other ( Candida albicans , Entamoeba coli in the gut)."],"dp":[]},"parasito-intro:e4":{"s":2,"u":["Dead end: unusual host, no adult stage (larva migrans, hydatid cyst in humans).","Parasitic dead end : infective form in an unusual host that never reaches adulthood but may cause disease (larva migrans).","Types : anthroponosis (humans only: ascariasis, amoebiasis, pinworm), anthropozoonosis (mainly animals: trichinosis, hydatid cyst), zoo-anthroponosis (mainly humans, animals in the cycle: taeniasis)."],"dp":[]},"parasito-intro:e5":{"s":2,"u":["Ectoparasite → infestation; endoparasite → infection.","Ectoparasites live on the surface (ticks, lice: infestation); endoparasites inside (hollow organs, tissues, cells: infection)."],"dp":[]},"parasito-intro:e6":{"s":3,"u":["Entry: ingestion, skin (Schistosoma), transplacental (Toxoplasma), bite (Plasmodium).","Entry : direct contact (ectoparasites), ingestion (amoebae, helminth eggs), inhalation (fungal spores), trans-cutaneous ( Schistosoma in fresh water), sexual ( Trichomonas ), transplacental ( Toxoplasma ), insect bite ( Plasmodium )."],"dp":[]},"parasito-intro:e7":{"s":4,"u":["Definitive host = adult/sexual; intermediate host = larval/asexual.","Intermediate host : larval or asexual forms.","Definitive host : adult or sexual forms."],"dp":[]},"parasito-intro:e8":{"s":4,"u":["Direct short (amoeba), direct long (Ancylostoma), indirect (Taenia).","Cycles: short direct (monoxenous, no outside maturation: amoebae), long direct (maturation in the environment: Ancylostoma ), indirect (heteroxenous: Taenia with pig or cattle; filariae with a vector), dead end (dog hookworm larvae in human skin)."],"dp":[]},"parasito-intro:e9":{"s":4,"u":["Pinworm: evening anal itch, scotch test, albendazole repeated at 15-21 days.","Example, pinworm ( Enterobius vermicularis ) : human reservoir and host, no HI or vector, cosmopolitan; embryonated eggs ingested or inhaled from hands, bedding, air; adults in 2-4 weeks; evening anal pruritus ; Graham scotch-tape test ; albendazole repeated 15-21 days later plus treating the household, hand washing, cutting nails, washing bedding (auto-infestation)."],"dp":[{"h":"Why pinworm treatment is repeated","t":"Albendazole kills adult worms but not all eggs, and a child re-infects themselves by scratching and swallowing eggs. The second dose 2-3 weeks later kills the worms that hatched in the meantime, and treating the household and washing bedding stops the loop. Source: the lecture's oxyurosis example."}]}},"meta":{"18sr8jl":{"a":"recall","vg":"parasito-intro:e0/recall/1"},"dxh9a":{"a":"recall","vg":"parasito-intro:e1/recall/1"},"9bw49c":{"a":"recall","vg":"parasito-intro:e3/recall/1"},"e91mmb":{"a":"recall","vg":"parasito-intro:e4/recall/1"},"w9nmo8":{"a":"recall","vg":"parasito-intro:e4/recall/2"},"9sf4ya":{"a":"recall","vg":"parasito-intro:e4/recall/3"},"m3zfqq":{"a":"recall","vg":"parasito-intro:e6/recall/1"},"z3mvie":{"a":"recall","vg":"parasito-intro:e6/recall/2"},"sl4sci":{"a":"recall","vg":"parasito-intro:e7/recall/1"},"otj3lh":{"a":"recall","vg":"parasito-intro:e7/recall/2"},"y9wmxt":{"a":"recall","vg":"parasito-intro:e8/recall/1"},"qs6e8j":{"a":"recall","vg":"parasito-intro:e8/recall/2"},"14a2ypq":{"a":"recall","vg":"parasito-intro:e9/recall/1"},"1ss3cqs":{"a":"recall","vg":"parasito-intro:e9/recall/2"},"1xgs4z1":{"a":"recall","vg":"parasito-intro:e4/recall/4"}},"explRev":"65dd2f6efcff"};
